import { AsyncLocalStorage } from 'node:async_hooks';

import type { Logger } from 'pino';

export interface RequestContext {
  /** `req_…`, always generated by the server (CONTRACTS §1.1). */
  readonly requestId: string;
  /** Child logger bound to `request_id` (and `client_request_id` when sent). */
  readonly logger: Logger;
}

/**
 * Per-request context, entered in the Fastify `onRequest` hook, so that
 * injected singletons (`AppLogger`) log with the current `request_id`.
 */
export const requestContext = new AsyncLocalStorage<RequestContext>();
